window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[136]={"id":"136","numero":136,"titre":"Anesthésie générale, locale et locorégionale","objectifs":[{"id":"136-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître le nombre d’actes annuel, les cinq interventions les plus fréquentes","contenu":"<p>L'anesthésie est l'un des actes médicaux les plus pratiqués en France. Plus de\n      <span class=\"kw-chiffre\">50 %</span> des actes sont aujourd'hui réalisés en\n      <span class=\"kw-def\">ambulatoire</span> (patient opéré et sortant le jour même), avec un\n      <strong>objectif à terme de <span class=\"kw-chiffre\">70 %</span></strong>.</p>\n      <p><strong>Les cinq interventions les plus fréquentes</strong> regroupent à elles seules\n      environ <span class=\"kw-chiffre\">1/3</span> de toutes les interventions réalisées sous anesthésie :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Endoscopies digestives</span></li>\n        <li><span class=\"kw-clinique\">Accouchements par voie basse et césariennes</span></li>\n        <li>Interventions sur le <span class=\"kw-clinique\">cristallin</span> (<em>cataracte</em>)</li>\n        <li>Chirurgie de la <span class=\"kw-clinique\">bouche et des dents</span></li>\n        <li>Libérations du <span class=\"kw-clinique\">canal carpien</span></li>\n      </ul>","frequence":0},{"id":"136-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la mortalité imputable à l’anesthésie","contenu":"<p>La <span class=\"kw-def\">mortalité directement imputable à l'anesthésie</span> a été\n      <strong>considérablement réduite</strong> en France, grâce aux\n      <span class=\"kw-def\">procédures de sécurité très rigoureuses</span> qui encadrent le processus\n      anesthésique et à son <span class=\"kw-def\">encadrement juridique</span> (décret anesthésie).</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Période</th><th>Mortalité imputable à l'anesthésie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Début des années 1980</td><td><span class=\"kw-chiffre\">1 décès pour 10 000</span> anesthésies</td></tr>\n          <tr><td>1999</td><td><span class=\"kw-chiffre\">1 pour 150 000</span></td></tr>\n          <tr><td>Actuellement</td><td><strong><span class=\"kw-chiffre\">1 pour 200 000</span></strong></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"136-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du décret anesthésie","contenu":"<p>Le <span class=\"kw-def\">décret anesthésie</span> impose que, pour tout patient dont l'état\n      nécessite une <span class=\"kw-def\">anesthésie générale</span> ou une\n      <span class=\"kw-def\">anesthésie locorégionale</span>, l'établissement de santé assure un socle\n      de garanties de sécurité.</p>\n      <p><strong>Les cinq garanties réglementaires</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Consultation pré-anesthésique</span> — lorsqu'il s'agit d'une intervention <strong>programmée</strong></li>\n        <li><span class=\"kw-def\">Visite pré-anesthésique</span></li>\n        <li>Mise à disposition des <strong>moyens nécessaires</strong> à la réalisation de l'anesthésie</li>\n        <li><span class=\"kw-clinique\">Surveillance continue</span> après l'intervention</li>\n        <li>Organisation permettant de <strong>faire face à tout moment</strong> à une complication liée à l'intervention ou à l'anesthésie</li>\n      </ul>\n      <div class=\"obj-callout info\"><strong>À retenir.</strong> Le <span class=\"kw-def\">passage en SSPI</span>\n      (salle de surveillance post-interventionnelle) est une étape <strong>obligatoire et incontournable</strong>\n      de la sécurité anesthésique au titre du décret.</div>","frequence":0},{"id":"136-4","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la consultation pré-anesthésique","contenu":"<p>La <span class=\"kw-def\">consultation pré-anesthésique</span> (CPA) est\n      <strong>obligatoire quel que soit le type d'anesthésie</strong> (AG et ALR). Elle\n      <span class=\"kw-alerte\">ne remplace pas la visite pré-anesthésique</span> (VPA), qui doit avoir\n      lieu dans les <span class=\"kw-chiffre\">&lt; 24 h</span> précédant l'intervention.\n      <strong>Seule exception</strong> : l'acte chirurgical en <span class=\"kw-alerte\">urgence</span>,\n      où seule la VPA est indispensable.</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th></th><th>Consultation pré-anesthésique (CPA)</th><th>Visite pré-anesthésique (VPA)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Délai</td>\n            <td><span class=\"kw-chiffre\">≥ 2 jours</span> (délai légal) avant un acte programmé ; idéal <span class=\"kw-chiffre\">1 à 2 semaines</span>, <span class=\"kw-chiffre\">≤ 3 mois</span></td>\n            <td>Dans les heures précédant l'intervention (<span class=\"kw-chiffre\">&lt; 24 h</span>)</td>\n          </tr>\n          <tr>\n            <td>Objet</td>\n            <td>Évaluation complète et choix de la stratégie anesthésique</td>\n            <td><strong>Confirmation</strong> des données de la CPA, vérification de l'absence d'événement nouveau (infection ORL, jeûne, traitements)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Qui réalise la CPA ?</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Médecin anesthésiste-réanimateur</span></li>\n        <li>Un <strong>interne d'anesthésie-réanimation</strong> peut la réaliser, mais doit <strong>obligatoirement en référer à un senior</strong></li>\n        <li>Le médecin qui réalise la CPA peut être <strong>différent</strong> de celui qui réalisera l'anesthésie le jour J</li>\n      </ul>\n      <p><strong>Objectifs de la CPA</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Évaluation médicale</span> du patient : antécédents, état clinique, traitements</li>\n        <li>Proposer la <strong>meilleure stratégie anesthésique</strong> (technique, stratégie transfusionnelle, prise en charge de la douleur et des <span class=\"kw-clinique\">nausées-vomissements post-opératoires</span>)</li>\n        <li>Définir les <span class=\"kw-bio\">examens complémentaires</span> utiles — <span class=\"kw-alerte\">ni systématiques ni obligatoires</span></li>\n        <li>Gérer les <span class=\"kw-ttt\">traitements en cours</span> et proposer une anxiolyse si nécessaire</li>\n        <li>Informer sur les <strong>règles de jeûne</strong> pré-anesthésique, <strong><span class=\"kw-etio\">tabac</span> inclus</strong></li>\n        <li>Informer sur la stratégie anesthésique et les <span class=\"kw-alerte\">complications potentielles</span></li>\n      </ul>\n      <p><strong>Règles de jeûne</strong> : pas d'alimentation <span class=\"kw-clinique\">solide</span> dans les\n      <span class=\"kw-chiffre\">6 h</span> précédant l'anesthésie, pas de <span class=\"kw-clinique\">liquide</span>\n      dans les <span class=\"kw-chiffre\">2 h</span>.</p>\n      <p><strong>Gestion des traitements à risque</strong> : arrêt des <span class=\"kw-ci\">IEC / ARA2</span>\n      <span class=\"kw-chiffre\">48 h</span> avant ; arrêt des <span class=\"kw-ci\">AVK</span> ± relais héparine\n      (sauf exception) ; arrêt des <span class=\"kw-ci\">antiagrégants plaquettaires</span> parfois, mais rare.</p>\n      <p>Les résultats sont consignés dans un <strong>document écrit</strong> inséré au dossier médical.\n      L'<span class=\"kw-def\">information orale</span> est primordiale ; le patient formule un\n      <strong><span class=\"kw-def\">consentement éclairé écrit</span></strong> à l'issue de la consultation.</p>\n      <div class=\"obj-callout info\"><strong>CPA en contexte d'urgence.</strong> L'évaluation anesthésique\n      urgente <span class=\"kw-alerte\">ne retarde en aucun cas l'intervention</span>. Trois situations :\n      <em>idéale</em> (consultation en chambre ou aux urgences) ; <em>détresse vitale</em> (consultation\n      au bloc, document parfois rempli a posteriori) ; <em>intermédiaire</em> (consultation à l'arrivée\n      au bloc, voire en salle juste avant l'anesthésie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — Antalgique</em></p>","frequence":5},{"id":"136-5","rang":"A","rubrique":"Définition","titre":"Connaître les différents types d’anesthésie","contenu":"<p>On distingue <strong>trois types d'anesthésie</strong>, selon que la conscience est abolie\n      ou préservée et selon l'étendue du territoire concerné.</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Type</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Anesthésie générale</span></strong></td>\n            <td><span class=\"kw-clinique\">Perte de conscience réversible</span> induite par un <span class=\"kw-ttt\">hypnotique</span>, souvent associé à un <span class=\"kw-ttt\">agent analgésique</span>. Un <span class=\"kw-ttt\">curare</span> est fréquemment employé pour provoquer une paralysie musculaire facilitant l'intubation trachéale et le geste chirurgical.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Anesthésie locorégionale</span></strong> (ALR)</td>\n            <td>Interruption <strong>transitoire</strong> de la conduction nerveuse <span class=\"kw-alerte\">tout en préservant l'état de conscience</span>. Selon le site d'injection, deux types : <strong>périmédullaire</strong> (autour de la moelle épinière) ou <strong>périphérique</strong> (autour du nerf).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Anesthésie locale</span></strong> (AL)</td>\n            <td>Administration d'un <span class=\"kw-ttt\">anesthésique local</span> en regard de la zone à opérer ou à analgésier, par <strong>infiltration</strong> (intradermique, sous-cutanée, plan de <span class=\"kw-imagerie\">diffusion</span>) ou par voie <strong>topique</strong> (contact). Réalisable par <strong>tout médecin</strong>, quelle que soit sa spécialité.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"136-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d’une anesthésie générale, indications, principales complications","contenu":"<p>L'<span class=\"kw-def\">anesthésie générale</span> reste la <strong>technique de référence</strong> :\n      elle permet de réaliser <strong>tous les actes</strong> chirurgicaux et interventionnels, en\n      urgence comme en programmé.</p>\n      <p><strong>Les phases de l'anesthésie générale</strong></p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Phase</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Préparation</strong></td>\n            <td>\n              <strong>Check-list :</strong> check-list HAS « sécurité au bloc opératoire » (identité, type d'intervention)<br>\n              <strong>Monitorage :</strong> <span class=\"kw-clinique\">VVP</span> ; monitorage multiparamétrique — <span class=\"kw-clinique\">FC</span> ; <span class=\"kw-clinique\">ECG</span> ; <span class=\"kw-clinique\">PA non invasive</span> ; <span class=\"kw-clinique\">SpO₂</span><br>\n              <strong>Antibioprophylaxie :</strong> si indiquée, administrée <span class=\"kw-chiffre\">30 min avant</span> l'incision<br>\n              <strong>Réchauffement :</strong> externe dès l'arrivée en salle, pour prévenir l'<span class=\"kw-alerte\">hypothermie péri-opératoire</span><br>\n              <strong>Pré-oxygénation :</strong> (dénitrogénation) au masque facial <span class=\"kw-chiffre\">FiO₂ 100 %</span>, pendant <span class=\"kw-chiffre\">≥ 3 min</span>, jusqu'à une fraction expirée d'O₂ <span class=\"kw-chiffre\">&gt; 90 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Induction</strong><br>(phase 1)</td>\n            <td><span class=\"kw-ttt\">Hypnotique</span> (perte de conscience) + <span class=\"kw-ttt\">analgésique opioïde</span> (contrôle de la réponse neurovégétative de stress) ; contrôle des voies aériennes (ventilation au masque facial, puis <span class=\"kw-clinique\">IOT</span> ou masque laryngé) ; <span class=\"kw-ttt\">curare</span> recommandé si une IOT est prévue</td>\n          </tr>\n          <tr>\n            <td><strong>Entretien</strong><br>(phase 2)</td>\n            <td><span class=\"kw-ttt\">Hypnotique</span> (constant) + <span class=\"kw-ttt\">opioïde</span> (souvent) ± <span class=\"kw-ttt\">curare</span> si relâchement musculaire complet nécessaire (chirurgie thoracique, abdominale) ; maintien de l'homéostasie ; <span class=\"kw-def\">analgésie multimodale</span> anticipée pour le post-opératoire (précoce, avant le réveil ; la <span class=\"kw-ttt\">morphine</span> est le produit de référence)</td>\n          </tr>\n          <tr>\n            <td><strong>Réveil</strong><br>(phase 3)</td>\n            <td>Arrêt des médicaments de l'anesthésie ; récupération d'un état de conscience normal ; débute en salle d'intervention puis se poursuit en <span class=\"kw-def\">SSPI</span> (salle de surveillance post-interventionnelle, « salle de réveil »)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Médicaments de l'anesthésie générale</strong></p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Classe</th><th>Mécanisme et exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Hypnotiques</span></strong></td>\n            <td>\n              <strong>Exemples :</strong> <span class=\"kw-ttt\">propofol</span> ; <span class=\"kw-ttt\">thiopental</span> ; <span class=\"kw-ttt\">kétamine</span><br>\n              <strong>Mécanisme :</strong> action agoniste sur les récepteurs <span class=\"kw-def\">GABA-A</span><br>\n              <strong>Exceptions :</strong> la <span class=\"kw-ttt\">kétamine</span> est antagoniste des récepteurs <span class=\"kw-def\">NMDA</span> du glutamate ; le <span class=\"kw-ttt\">protoxyde d'azote</span> (N₂O) a une double action mais n'est que très peu utilisé\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Analgésiques morphiniques</span></strong></td>\n            <td>Morphiniques de synthèse dérivés du <span class=\"kw-ttt\">fentanyl</span> ; <strong>agonistes purs</strong> des récepteurs <span class=\"kw-def\">µ</span> opioïdes (pas d'effet plafond) ; peu ou pas de métabolites actifs ; la <span class=\"kw-ttt\">morphine</span> est réservée à l'<strong>analgésie post-opératoire</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Curares</span></strong></td>\n            <td>Bloquent les récepteurs <span class=\"kw-def\">nicotiniques</span> de la jonction neuromusculaire → paralysie des muscles striés ; la <span class=\"kw-ttt\">succinylcholine</span> est le <strong>seul curare dépolarisant</strong> (fasciculations, action la plus rapide et la plus courte) ; antagonisation possible par la <span class=\"kw-ttt\">prostigmine</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de l'anesthésie générale</strong> (hors complications chirurgicales)</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Type</th><th>Complications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Respiratoires</strong></td>\n            <td>Accès difficile aux voies aériennes avec <span class=\"kw-alerte\">risque d'hypoxémie majeure</span> ; <span class=\"kw-alerte\">inhalation</span> de liquide gastrique chez un patient non à jeun ; <span class=\"kw-alerte\">bronchospasme</span> (asthmatique, anaphylaxie médicamenteuse)</td>\n          </tr>\n          <tr>\n            <td><strong>Hémodynamiques</strong></td>\n            <td><span class=\"kw-alerte\">Choc anaphylactique</span> (curare, antibiotique, latex) ; hypotension sévère par surdosage en anesthésique ; <span class=\"kw-alerte\">hyperthermie maligne</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout danger\"><strong>Piège.</strong> Tous les médicaments de l'anesthésie moderne\n      sont <strong>éliminés rapidement</strong>. Devant un <span class=\"kw-alerte\">trouble de la vigilance,\n      un coma ou une confusion plusieurs heures après une AG</span>, il ne faut <strong>pas</strong>\n      incriminer l'anesthésie : rechercher en premier lieu une autre cause — <span class=\"kw-etio\">sepsis</span>,\n      <span class=\"kw-etio\">hémorragie</span>, désordre hydro-électrolytique, <span class=\"kw-etio\">hypoglycémie</span>,\n      trouble de l'hématose, voire un <span class=\"kw-etio\">AVC</span> (surtout si hypotension per-opératoire).</div>\n      <div class=\"obj-callout\"><strong>Induction en séquence rapide (ISR).</strong> Technique d'AG de\n      l'urgence chez le patient « <strong>estomac plein</strong> » (polytraumatisé, gastroparésie\n      diabétique, antécédent de chirurgie bariatrique, RGO). Protocole : <span class=\"kw-ttt\">hypnotique</span>\n      + <span class=\"kw-ttt\">succinylcholine</span>, <strong><span class=\"kw-alerte\">sans morphinique</span></strong>\n      (délai d'action trop long, baisse des réflexes de protection des voies aériennes).</div>\n      <p><strong>Passage en SSPI</strong> : obligatoire (décret sécurité). Aucune durée minimale de\n      surveillance n'est recommandée, <strong>sauf</strong> au décours d'une <span class=\"kw-ttt\">titration\n      de morphine</span> (<span class=\"kw-chiffre\">≥ 1 h</span> de surveillance après le dernier bolus). La\n      sortie repose sur des critères objectifs : retour à la normale des fonctions vitales, absence de\n      complication, contrôle de la douleur.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - anaphylaxie · 332 — Etat de choc · 229 — Surveillance-complications abords veineux</em></p>","frequence":1},{"id":"136-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","contenu":"<p>L'<span class=\"kw-def\">anesthésie locorégionale</span> interrompt transitoirement la conduction\n      nerveuse sans abolir la conscience. Elle se décline en ALR <strong>centrale</strong>\n      (périmédullaire) et <strong>périphérique</strong>. L'<span class=\"kw-def\">anesthésie locale</span>\n      agit, elle, directement en regard de la zone à traiter.</p>\n      <p><strong>ALR centrale (périmédullaire)</strong> — réalisée par une ponction médiane lombaire\n      <strong>en dessous de <span class=\"kw-chiffre\">L2</span></strong> (niveau théorique du cône terminal),\n      patient assis ou en décubitus latéral. Deux techniques :</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th></th><th>Rachi-anesthésie</th><th>Anesthésie péridurale</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Site d'injection</td>\n            <td>Anesthésique local dans le <span class=\"kw-bio\">liquide cérébrospinal</span> (l'aiguille franchit la dure-mère)</td>\n            <td>Anesthésique local dans l'<span class=\"kw-def\">espace péridural</span> (entre dure-mère et ligament jaune)</td>\n          </tr>\n          <tr>\n            <td>Aiguille</td>\n            <td>Petit diamètre (<span class=\"kw-chiffre\">25-27 G</span>) — limite les <span class=\"kw-clinique\">céphalées</span> post-brèche</td>\n            <td>Aiguille de <strong>Tuohy</strong>, grand calibre (<span class=\"kw-chiffre\">16-18 G</span>) + <strong>cathéter</strong> multiperforé laissé en place</td>\n          </tr>\n          <tr>\n            <td>Bon positionnement</td>\n            <td><span class=\"kw-clinique\">Reflux de liquide cérébrospinal</span></td>\n            <td><span class=\"kw-clinique\">Perte de résistance</span> brutale à la pression du piston</td>\n          </tr>\n          <tr>\n            <td>Délai</td>\n            <td>Quelques <span class=\"kw-chiffre\">minutes</span></td>\n            <td>Plus lente</td>\n          </tr>\n          <tr>\n            <td>Zone anesthésiée</td>\n            <td>Hémicorps inférieur</td>\n            <td>Anesthésie suspendue (blocage métamérique)</td>\n          </tr>\n          <tr>\n            <td>Avantages</td>\n            <td>Technique simple ; risque traumatique moindre (aiguille fine)</td>\n            <td>Tout type d'intervention ; titration des doses via cathéter ; meilleure analgésie post-opératoire prolongée</td>\n          </tr>\n          <tr>\n            <td>Inconvénients</td>\n            <td>Risque hémodynamique <span class=\"kw-alerte\">non contrôlable</span> ; n'endort que la moitié inférieure du corps</td>\n            <td>Technique complexe, risque d'échec ; risque d'<span class=\"kw-alerte\">hématome</span> et de <span class=\"kw-alerte\">brèche dure-mérienne</span> majoré ; risque infectieux du cathéter</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de l'ALR centrale</strong> — deux mécanismes :</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Mécanisme</th><th>Complications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Liées à l'anesthésique</strong></td>\n            <td>\n              <strong>Anaphylaxie :</strong> réactions anaphylactiques<br>\n              <strong>Toxicité systémique :</strong> neurologique jusqu'à la <span class=\"kw-alerte\">crise convulsive généralisée</span> ; cardiaque jusqu'à l'<span class=\"kw-alerte\">arrêt cardiaque</span><br>\n              <strong>Hémodynamique :</strong> bloc sympathique → vasoplégie ; <span class=\"kw-alerte\">hypotension majeure si bloc au-dessus de T10</span><br>\n              <strong>Respiratoires :</strong> si niveau de bloc trop élevé (muscles respiratoires)<br>\n              <strong>Urinaires :</strong> difficultés mictionnelles jusqu'à la <span class=\"kw-clinique\">rétention aiguë d'urine</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Liées au geste</strong></td>\n            <td>\n              <strong>Hématome :</strong> hématome péridural, favorisé par une coagulopathie préexistante<br>\n              <strong>Infection :</strong> <span class=\"kw-def\">méningite</span> ; abcès péridural<br>\n              <strong>Neurologique :</strong> séquelle neurologique <span class=\"kw-chiffre\">&lt; 1/150 000</span> péridurales<br>\n              <strong><span class=\"kw-clinique\">Céphalées</span> :</strong> sur brèche dure-mérienne (risque majoré avec l'aiguille de péridurale)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>ALR périphérique</strong> — administration de l'anesthésique local au niveau d'un\n      <strong>plexus</strong> ou d'un <strong>tronc nerveux</strong>, contingents nerveux repérés par\n      <span class=\"kw-imagerie\">échographie</span> : plexus brachial (membre supérieur), plexus lombaire et\n      sacré (membre inférieur), rameaux de la Ve paire crânienne (face). Complications : réactions\n      anaphylactiques, surdosage avec double toxicité (<span class=\"kw-alerte\">neurologique + cardiaque</span>),\n      <span class=\"kw-alerte\">neuropathie</span> par lésion directe du nerf, abcès au point de ponction.</p>\n      <p><strong>Anesthésie locale</strong> — voie topique (collyre) ou infiltration intradermique /\n      sous-cutanée. Réalisable par <strong>tout médecin formé</strong>. Délai d'action quasi immédiat\n      (<span class=\"kw-chiffre\">1 à 2 min</span>), durée d'environ <span class=\"kw-chiffre\">60 min</span> pour la\n      <span class=\"kw-ttt\">lidocaïne</span>.</p>\n      <p><strong>Contre-indications</strong> des AL et ALR :</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Contre-indication</th><th>AL</th><th>ALR périph.</th><th>ALR centrale</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\">Refus du patient</span></td><td>X</td><td>X</td><td>X</td></tr>\n          <tr><td><span class=\"kw-ci\">Allergie aux anesthésiques locaux</span></td><td>X</td><td>X</td><td>X</td></tr>\n          <tr><td><span class=\"kw-ci\">Infection au site de ponction</span></td><td>X</td><td>X</td><td>X</td></tr>\n          <tr><td><span class=\"kw-ci\">Troubles de l'hémostase</span> (traitements inclus)</td><td>—</td><td>X</td><td>X</td></tr>\n          <tr><td><span class=\"kw-ci\">Hypertension intra-crânienne</span></td><td>—</td><td>—</td><td>X</td></tr>\n          <tr><td><span class=\"kw-ci\">Cardiopathie évoluée</span></td><td>—</td><td>—</td><td>X (relative)</td></tr>\n        </tbody>\n      </table>\n      <p>Pour les troubles de l'hémostase, l'<span class=\"kw-ttt\">aspirine à faible posologie</span>\n      n'est <strong>pas</strong> une contre-indication. La cardiopathie évoluée est une\n      <strong>contre-indication relative</strong> à l'ALR centrale, après évaluation du rapport\n      bénéfice/risque.</p>\n      <div class=\"obj-callout danger\"><strong>Urgence — Intoxication aux anesthésiques locaux.</strong><br>\n        <strong>Prévention :</strong> respect des doses maximales ; test d'aspiration avant l'injection ; injection fractionnée ; vitesse lente d'injection ; maintien du contact verbal.<br>\n        <strong>Clinique :</strong> signes neurologiques (acouphènes, dysesthésies péribuccales, goût métallique, sensation ébrieuse) jusqu'aux <span class=\"kw-alerte\">convulsions généralisées</span> et au <span class=\"kw-alerte\">coma</span> ; signes cardiaques (troubles du rythme) jusqu'à l'<span class=\"kw-alerte\">arrêt cardiaque</span>.<br>\n        <strong>Prise en charge :</strong> arrêt de l'injection ; appel à l'aide ; <span class=\"kw-ttt\">oxygène 100 %</span> ; <span class=\"kw-ttt\">benzodiazépine IV</span> anticomitiale ; traitement symptomatique du <span class=\"kw-clinique\">coma</span> et de l'arrêt cardiaque <strong><span class=\"kw-alerte\">sans aucun antiarythmique</span></strong> ; antidote = <span class=\"kw-ttt\">émulsion lipidique IV</span> (<span class=\"kw-chiffre\">3 mL/kg</span>).</div>\n      <div class=\"obj-callout info\"><strong>Règles de sécurité.</strong> Le principal risque de l'ALR est\n      son <strong>échec</strong>. Tout patient prévu pour une ALR, même exclusive, répond aux\n      <strong>mêmes règles que l'AG</strong> : CPA + VPA, VVP et monitorage multiparamétrique, passage\n      en SSPI — sauf AL topique ou ALR périphérique sans sédatif, patient stable et sans complication,\n      où la surveillance peut se faire dans un espace adapté.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 331 — Arrêt cardio-circulatoire · 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - anaphylaxie</em></p>","frequence":3},{"id":"136-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître le mécanisme d’action des anesthésiques locaux","contenu":"<p>Les <span class=\"kw-ttt\">anesthésiques locaux</span> agissent au niveau de la\n      <span class=\"kw-def\">conduction nerveuse</span> : ils <strong>bloquent les\n      <span class=\"kw-def\">canaux sodiques voltage-dépendants</span></strong> de la fibre nerveuse.</p>\n      <p>Conséquence : le <span class=\"kw-def\">potentiel d'action</span> ne peut plus être conduit le\n      long de la fibre nerveuse, ce qui interrompt la transmission du message nerveux — sensitif, et\n      à plus forte dose moteur.</p>","frequence":0},{"id":"136-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux anesthésiques locaux","contenu":"<p>Les principaux <span class=\"kw-ttt\">anesthésiques locaux</span> utilisés en pratique :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Bupivacaïne</span></li>\n        <li><span class=\"kw-ttt\">Ropivacaïne</span></li>\n        <li><span class=\"kw-ttt\">Mépivacaïne</span></li>\n        <li><span class=\"kw-ttt\">Lidocaïne</span></li>\n      </ul>\n      <p>Tous partagent le même mécanisme d'action (blocage des <span class=\"kw-def\">canaux sodiques\n      voltage-dépendants</span>). Pour l'anesthésie locale, le délai d'action est quasi immédiat\n      (<span class=\"kw-chiffre\">1 à 2 min</span>) et la durée d'environ <span class=\"kw-chiffre\">60 min</span>\n      pour la <span class=\"kw-ttt\">lidocaïne</span>.</p>","frequence":0},{"id":"136-10","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme de la douleur pendant le travail et l’accouchement","contenu":"<p>Les douleurs du travail et de l'accouchement sont de <strong>deux types</strong> —\n      <span class=\"kw-def\">viscérales</span> et <span class=\"kw-def\">somatiques</span> — qui se\n      succèdent au cours du travail.</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Phase</th><th>Origine et voies de la douleur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ phase du travail</strong></td>\n            <td>\n              <strong>Contractions utérines :</strong> douleur véhiculée par les <span class=\"kw-def\">fibres Aδ</span><br>\n              <strong>Effacement et dilatation du col :</strong> influx douloureux <span class=\"kw-def\">viscéral</span> véhiculé par les <span class=\"kw-def\">fibres C non myélinisées</span><br>\n              <strong>Relais :</strong> fibres C et fibres Aδ font relais à la <span class=\"kw-def\">corne postérieure de la moelle</span>, de <span class=\"kw-chiffre\">T10 à L1</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fin de 1ʳᵉ et 2ᵉ phase</strong></td>\n            <td>\n              <strong>Origine :</strong> douleur <span class=\"kw-def\">somatique</span>, secondaire à la distension du plancher pelvien, du vagin et du périnée<br>\n              <strong>Voies :</strong> transmise par les <span class=\"kw-def\">nerfs honteux</span>, issus des racines sacrées <span class=\"kw-chiffre\">S2-S4</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 134 — Bases neurophysiologiques de la douleur</em></p>","frequence":0},{"id":"136-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","contenu":"<p>Les <span class=\"kw-ttt\">morphiniques systémiques</span> ne contrôlent que partiellement les\n      douleurs somatiques et sont <span class=\"kw-alerte\">inefficaces sur les douleurs viscérales</span>\n      du travail. L'<span class=\"kw-def\">analgésie péri-médullaire</span> est la <strong>seule\n      technique</strong> à assurer une analgésie de qualité durant tout le travail obstétrical.</p>\n      <table class=\"descriptif-table\">\n        <thead>\n          <tr><th>Technique</th><th>Place en obstétrique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Rachi-anesthésie</span></strong></td>\n            <td>Souvent pratiquée pour la <strong>césarienne</strong> : rapidité, simplicité de mise en place, moindre risque de <span class=\"kw-clinique\">céphalées</span> post-ponction</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Péridurale lombaire</span></strong></td>\n            <td><strong>Technique de référence</strong> en analgésie obstétricale. Grâce au <span class=\"kw-def\">cathéter péridural</span> posé pendant le travail : approfondissement de l'anesthésie pour une césarienne ; analgésie prolongée par perfusion continue ; auto-administration de bolus par la parturiente</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications spécifiques au contexte obstétrical</strong> :</p>\n      <ul>\n        <li><strong>Échec d'analgésie</strong> par <span class=\"kw-alerte\">malposition du cathéter</span> de péridurale (posé à l'aveugle) — c'est la complication <strong>la plus fréquente</strong> (<span class=\"kw-chiffre\">1/100</span>)</li>\n        <li><span class=\"kw-alerte\">Bloc moteur</span> : la patiente ne peut plus mobiliser ses membres inférieurs ni maîtriser ses efforts abdomino-pelviens</li>\n        <li><span class=\"kw-alerte\">Hypotension maternelle</span>, avec risque de retentissement fœtal (<span class=\"kw-alerte\">souffrance fœtale</span>)</li>\n      </ul>\n      <p><strong>Prévention</strong> : utilisation de <strong>faibles concentrations</strong>\n      d'anesthésiques locaux + un ou plusieurs <strong>adjuvants</strong> pour potentialiser les effets\n      sensitifs (généralement un opioïde comme le <span class=\"kw-ttt\">sufentanil</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 135 — Antalgique</em></p>","frequence":0},{"id":"136-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître la réhabilitation précoce après chirurgie (RAC) et chirurgie ambulatoire","contenu":"<p>La <span class=\"kw-def\">réhabilitation améliorée après chirurgie</span> (RAC, ou RAAC) est une\n      prise en charge <strong>globale et pluriprofessionnelle</strong> (opérateur, anesthésiste-réanimateur,\n      infirmier, kinésithérapeute) du patient tout au long de son parcours péri-opératoire.</p>\n      <p><strong>Objectifs</strong> : permettre au patient de <strong>retrouver son autonomie le plus\n      rapidement possible</strong> → réduction de la <span class=\"kw-alerte\">morbidité</span> et des\n      <strong>durées d'hospitalisation</strong>. La <strong>gestion de la douleur en est le pilier\n      central</strong> ; elle favorise la mobilisation précoce. Le programme s'appuie sur un\n      <span class=\"kw-def\">chemin clinique</span> couvrant les <strong>trois phases</strong> : avant,\n      pendant et après la chirurgie.</p>\n      <p><strong>Points clés du programme RAAC</strong> :</p>\n      <ul>\n        <li>Informer le patient et le former à la démarche</li>\n        <li>Anticiper l'organisation des soins et la sortie du patient</li>\n        <li>Réduire les conséquences du <strong>stress chirurgical</strong></li>\n        <li>Contrôler la <span class=\"kw-clinique\">douleur</span> dans toutes les situations</li>\n        <li>Favoriser et stimuler l'autonomie du patient</li>\n      </ul>\n      <p><strong>Chirurgie ambulatoire</strong> — patient opéré et sortant à domicile <strong>le jour\n      même</strong> ; elle constitue un objectif de santé publique (réduction des coûts\n      d'hospitalisation). Plusieurs <strong>critères</strong> sont indispensables :</p>\n      <ul>\n        <li>Accord du patient et parfaite compréhension des consignes post-opératoires</li>\n        <li>Domicile suffisamment proche de l'établissement de santé</li>\n        <li>Mode de vie non isolé</li>\n        <li>Collaboration avec les professionnels de soins à domicile (médecin traitant, paramédicaux)</li>\n        <li>Possibilité de joindre l'équipe médico-chirurgicale à tout moment</li>\n      </ul>\n      <p>Elle est réservée à certaines interventions sans complication et à des patients sans\n      comorbidité importante.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — Antalgique</em></p>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/anesthesiques-generaux","label":"pharmacomedicale.org"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/anesthesiques-locaux","label":"pharmacomedicale.org"}],"cards":[{"i":"0fe085b80e3c","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Quelle est la complication la plus fréquente de l'analgésie périmédullaire en obstétrique et quelle en est la cause ?","a":"<p>La complication la plus fréquente est l'<strong>échec d'analgésie</strong> (incidence de <strong>1/100</strong>), dû à une <strong>malposition du cathéter de péridurale</strong>, ce dernier étant posé à l'aveugle.</p>"},{"i":"1c9329822412","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Quels sont les inconvénients des morphiniques systémiques dans le contrôle de la douleur du travail obstétrical ?","a":"<p>Les morphiniques systémiques ne contrôlent que <strong>partiellement les douleurs somatiques</strong> et sont <strong>inefficaces sur les douleurs viscérales</strong> du travail obstétrical.</p>"},{"i":"5b03665a0a60","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Quelle est la technique d'analgésie de référence pour le travail obstétrical, et pourquoi ?","a":"<p>La technique de référence est l'<strong>analgésie péridurale lombaire</strong>. Elle est privilégiée car grâce au cathéter péridural, elle permet une analgésie prolongée par perfusion continue ou l'auto-administration de bolus par la parturiente, et peut être approfondie pour une césarienne.</p>"},{"i":"aea2b591678d","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Quelles sont les autres complications spécifiques de l'analgésie périmédullaire en contexte obstétrical ?","a":"<ul><li>Le <strong>bloc moteur</strong> : la patiente ne peut plus mobiliser ses membres inférieurs ni maîtriser ses efforts abdomino-pelviens.</li><li>L'<strong>hypotension maternelle</strong> : avec un risque de retentissement fœtal (souffrance fœtale).</li></ul>"},{"i":"b351b60ac35d","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Comment prévenir l'hypotension maternelle et le bloc moteur lors d'une analgésie périmédullaire en obstétrique ?","a":"<p>Ces complications sont prévenues par l'utilisation de <strong>faibles concentrations d'anesthésiques locaux</strong>, associées à un ou plusieurs <strong>adjuvants</strong> (généralement un <strong>opioïde comme le sufentanil</strong>) pour potentialiser les effets sensitifs.</p>"},{"i":"e349c58daa8f","n":136,"o":"136-11","u":"Prise en charge","t":"Connaître les principes d’une analgésie/anesthésie obstétricale, les principales complications","q":"Quelle est la technique anesthésique la plus couramment utilisée pour une césarienne et quels sont ses avantages ?","a":"<p>La <strong>rachi-anesthésie</strong> est souvent pratiquée pour la césarienne. Ses avantages sont la <strong>rapidité</strong> et la <strong>simplicité de mise en place</strong>, ainsi qu'un <strong>moindre risque de céphalées post-ponction</strong> par rapport à d'autres techniques.</p>"},{"i":"503d72a1a4cc","n":136,"o":"136-2","u":"Epidémiologie","t":"Connaître la mortalité imputable à l’anesthésie","q":"Comment a évolué la mortalité directement imputable à l'anesthésie en France au fil du temps ?","a":"<p>La mortalité directement imputable à l'anesthésie a <strong>considérablement diminué</strong> en France :</p><ul><li>Début des années 1980 : <strong>1 décès pour 10 000</strong> anesthésies.</li><li>1999 : <strong>1 décès pour 150 000</strong> anesthésies.</li><li>Actuellement : environ <strong>1 décès pour 200 000</strong> anesthésies.</li></ul>"},{"i":"773b20f220c0","n":136,"o":"136-2","u":"Epidémiologie","t":"Connaître la mortalité imputable à l’anesthésie","q":"Quels sont les facteurs principaux ayant contribué à la réduction de la mortalité directement imputable à l'anesthésie en France ?","a":"<p>Les facteurs principaux sont :</p><ul><li>Des <strong>procédures de sécurité très rigoureuses</strong> encadrant le processus anesthésique.</li><li>Un <strong>encadrement juridique strict</strong> (notamment le décret anesthésie).</li></ul>"},{"i":"74031a4876ec","n":136,"o":"136-3","u":"Prise en charge","t":"Connaître les principes du décret anesthésie","q":"Quels sont les cinq piliers du socle de garanties de sécurité imposé par le décret anesthésie ?","a":"<ul><li>La <strong>consultation pré-anesthésique</strong> (pour les interventions programmées).</li><li>La <strong>visite pré-anesthésique</strong>.</li><li>La mise à disposition des <strong>moyens nécessaires</strong> à la réalisation de l'anesthésie.</li><li>La <strong>surveillance continue</strong> après l'intervention.</li><li>Une organisation permettant de faire face à tout moment à une <strong>complication liée à l'intervention ou à l'anesthésie</strong>.</li></ul>"},{"i":"d05c4ff1313e","n":136,"o":"136-3","u":"Prise en charge","t":"Connaître les principes du décret anesthésie","q":"Quelle étape post-interventionnelle est rendue obligatoire par le décret anesthésie pour la sécurité des patients ?","a":"<p>Le <strong>passage en Salle de Surveillance Post-Interventionnelle (SSPI)</strong> est une étape obligatoire et incontournable de la sécurité anesthésique selon le décret.</p>"},{"i":"e961ec3aff49","n":136,"o":"136-3","u":"Prise en charge","t":"Connaître les principes du décret anesthésie","q":"Quel type d'anesthésie est concerné par le décret anesthésie en France ?","a":"<p>Le décret anesthésie concerne les patients nécessitant une <strong>anesthésie générale</strong> ou une <strong>anesthésie locorégionale</strong>.</p>"},{"i":"010184184631","n":136,"o":"136-4","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Quels sont les objectifs essentiels de la consultation pré-anesthésique (CPA) en vue d'une intervention chirurgicale ?","a":"<ul><li>Évaluation médicale complète du patient (antécédents, état clinique, traitements en cours).</li><li>Proposition de la meilleure <strong>stratégie anesthésique</strong> (technique, gestion de la douleur post-opératoire, prévention des nausées-vomissements).</li><li>Définition des <strong>examens complémentaires utiles</strong> (non systématiques).</li><li>Gestion des traitements en cours et proposition d'une <strong>anxiolyse</strong> si nécessaire.</li><li>Information du patient sur les <strong>règles de jeûne</strong> (solides <strong>6h</strong>, liquides <strong>2h</strong>) et les complications potentielles.</li><li>Obtention du <strong>consentement éclairé écrit</strong> du patient.</li></ul>"},{"i":"1853193f6cba","n":136,"o":"136-4","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Comment la consultation pré-anesthésique (CPA) est-elle adaptée en situation d'urgence chirurgicale ?","a":"<p>L'évaluation anesthésique d'urgence <strong>ne doit en aucun cas retarder l'intervention</strong>. Elle peut se dérouler selon trois modalités :</p><ul><li><strong>Idéale</strong> : consultation en chambre ou aux urgences.</li><li><strong>Intermédiaire</strong> : consultation à l'arrivée au bloc, voire juste avant l'anesthésie.</li><li><strong>Détresse vitale</strong> : consultation au bloc, avec un document parfois rempli <em>a posteriori</em>.</li></ul>"},{"i":"fb5a6916d9ae","n":136,"o":"136-4","u":"Prise en charge","t":"Connaître les principes de la consultation pré-anesthésique","q":"Quelle est la principale différence de délai entre la consultation pré-anesthésique (CPA) et la visite pré-anesthésique (VPA) en anesthésie ?","a":"<p>La <strong>consultation pré-anesthésique (CPA)</strong> doit être réalisée <strong>au moins 2 jours</strong> avant l'acte programmé, idéalement 1 à 2 semaines avant, et est valide <strong>jusqu'à 3 mois</strong>. La <strong>visite pré-anesthésique (VPA)</strong>, en revanche, a lieu dans les <strong>heures précédant l'intervention</strong>, soit moins de 24 heures avant.</p>"},{"i":"1bcd0ec578e2","n":136,"o":"136-5","u":"Définition","t":"Connaître les différents types d’anesthésie","q":"Quelle est la définition de l'anesthésie locorégionale ?","a":"<p>L'anesthésie locorégionale (ALR) est une <strong>interruption transitoire de la conduction nerveuse</strong>, tout en <strong>préservant l'état de conscience</strong>.</p>"},{"i":"3432876a9032","n":136,"o":"136-5","u":"Définition","t":"Connaître les différents types d’anesthésie","q":"Quelle est la définition de l'anesthésie générale ?","a":"<p>L'anesthésie générale est une <strong>perte de conscience réversible</strong> induite par un <strong>hypnotique</strong>, souvent associé à un agent analgésique. Un <strong>curare</strong> est fréquemment employé pour provoquer une <strong>paralysie musculaire</strong>, facilitant l'intubation trachéale et le geste chirurgical.</p>"},{"i":"4042ac332f14","n":136,"o":"136-5","u":"Définition","t":"Connaître les différents types d’anesthésie","q":"Par quelles voies peut-on réaliser une anesthésie locale ?","a":"<ul><li>Par <strong>infiltration</strong> : intradermique, sous-cutanée, ou par plan de diffusion.</li><li>Par <strong>voie topique</strong> : par contact.</li></ul>"},{"i":"878e8fab9e0d","n":136,"o":"136-5","u":"Définition","t":"Connaître les différents types d’anesthésie","q":"Quelle est la définition de l'anesthésie locale ?","a":"<p>L'anesthésie locale (AL) est l'administration d'un <strong>anesthésique local</strong> en regard de la zone à opérer ou à analgésier.</p>"},{"i":"f53884d40d98","n":136,"o":"136-5","u":"Définition","t":"Connaître les différents types d’anesthésie","q":"Quels sont les différents types d'anesthésie locorégionale selon le site d'injection ?","a":"<ul><li><strong>Périmédullaire</strong> : autour de la moelle épinière.</li><li><strong>Périphérique</strong> : autour du nerf.</li></ul>"},{"i":"32d31193a8e7","n":136,"o":"136-6","u":"Prise en charge","t":"Connaître les principes d’une anesthésie générale, indications, principales complications","q":"Que faire devant un trouble de la vigilance ou un coma qui survient plusieurs heures après une anesthésie générale ?","a":"<p>Étant donné que les médicaments de l'anesthésie moderne sont rapidement éliminés, un trouble de la vigilance ou un coma persistant plusieurs heures après une anesthésie générale ne doit pas incriminer l'anesthésie comme cause principale. Il faut rechercher en priorité d'autres étiologies, telles que :</p><ul><li>Un <strong>sepsis</strong>.</li><li>Une <strong>hémorragie</strong>.</li><li>Un <strong>désordre hydro-électrolytique</strong>.</li><li>Une <strong>hypoglycémie</strong>.</li><li>Un <strong>trouble de l'hématose</strong>.</li><li>Un <strong>AVC</strong>, surtout si une hypotension per-opératoire a eu lieu.</li></ul>"},{"i":"5a8ed57b4b54","n":136,"o":"136-6","u":"Prise en charge","t":"Connaître les principes d’une anesthésie générale, indications, principales complications","q":"Quelles sont les principales classes de médicaments utilisées en anesthésie générale et leur mécanisme d'action général ?","a":"<p>Les principales classes de médicaments sont :</p><ul><li>Les <strong>Hypnotiques</strong> : agissent principalement comme agonistes des récepteurs <strong>GABA-A</strong> (ex: propofol, thiopental). La kétamine est une exception, agissant comme antagoniste des récepteurs NMDA.</li><li>Les <strong>Analgésiques morphiniques</strong> : agonistes purs des récepteurs <strong>µ opioïdes</strong>, sans effet plafond (ex: dérivés du fentanyl pour l'entretien, morphine pour le post-opératoire).</li><li>Les <strong>Curares</strong> : bloquent les récepteurs <strong>nicotiniques de la jonction neuromusculaire</strong>, entraînant une paralysie des muscles striés (ex: succinylcholine comme curare dépolarisant, antagonisables par la prostigmine).</li></ul>"},{"i":"721da959d8ad","n":136,"o":"136-6","u":"Prise en charge","t":"Connaître les principes d’une anesthésie générale, indications, principales complications","q":"Quelle est la particularité de la technique d'Induction en Séquence Rapide (ISR) en anesthésie générale et dans quelles situations est-elle indiquée ?","a":"<p>L'<strong>Induction en Séquence Rapide (ISR)</strong> est une technique d'anesthésie générale utilisée en urgence pour les patients à <strong>estomac plein</strong> afin de minimiser le risque d'inhalation de liquide gastrique. Elle se caractérise par :</p><ul><li>L'administration rapide d'un <strong>hypnotique</strong> et de <strong>succinylcholine</strong>.</li><li>L'absence de morphinique pour éviter le délai d'action long et la baisse des réflexes de protection des voies aériennes.</li></ul><p>Elle est indiquée chez les patients polytraumatisés, en cas de gastroparésie diabétique, d'antécédent de chirurgie bariatrique, ou de RGO.</p>"},{"i":"bbde8c960a94","n":136,"o":"136-6","u":"Prise en charge","t":"Connaître les principes d’une anesthésie générale, indications, principales complications","q":"Quelles sont les complications respiratoires et hémodynamiques principales de l'anesthésie générale, hors complications chirurgicales ?","a":"<p>Les principales complications sont :</p><ul><li><strong>Respiratoires</strong> :<ul><li>Accès difficile aux voies aériennes avec risque d'<strong>hypoxémie majeure</strong>.</li><li><strong>Inhalation de liquide gastrique</strong> (chez un patient non à jeun).</li><li><strong>Bronchospasme</strong> (patient asthmatique ou anaphylaxie médicamenteuse).</li></ul></li><li><strong>Hémodynamiques</strong> :<ul><li><strong>Choc anaphylactique</strong> (aux curares, antibiotiques, latex).</li><li><strong>Hypotension sévère</strong> (par surdosage en anesthésique).</li><li><strong>Hyperthermie maligne</strong>.</li></ul></li></ul>"},{"i":"c4424ae1164f","n":136,"o":"136-6","u":"Prise en charge","t":"Connaître les principes d’une anesthésie générale, indications, principales complications","q":"Quelles sont les 3 phases principales de l'anesthésie générale (AG) ?","a":"<p>Les trois phases principales de l'anesthésie générale sont :</p><ul><li>La phase d'<strong>Induction</strong> : perte de conscience et contrôle des voies aériennes.</li><li>La phase d'<strong>Entretien</strong> : maintien de l'hypnose, de l'analgésie et de l'homéostasie.</li><li>La phase de <strong>Réveil</strong> : récupération de la conscience, débutant en salle d'intervention et se poursuivant en SSPI (Salle de Surveillance Post-Interventionnelle).</li></ul>"},{"i":"1d4949c94dd1","n":136,"o":"136-7","u":"Prise en charge","t":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","q":"Quelles sont les contre-indications communes à l'anesthésie locale et locorégionale ?","a":"<p>Les contre-indications communes à l'anesthésie locale (AL) et/ou locorégionale (ALR) sont :</p><ul><li>Le <strong>refus du patient</strong>.</li><li>Une <strong>allergie</strong> connue aux anesthésiques locaux.</li><li>Une <strong>infection</strong> au site de ponction ou d'injection.</li><li>Des <strong>troubles de l'hémostase</strong> (y compris les traitements anticoagulants), sauf l'aspirine à faible posologie qui n'est pas une contre-indication.</li></ul>"},{"i":"58001c136a5b","n":136,"o":"136-7","u":"Prise en charge","t":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","q":"Quelles sont les caractéristiques principales comparées de la rachi-anesthésie et de l'anesthésie péridurale ?","a":"<ul><li><strong>Site d'injection</strong> : Rachi-anesthésie dans le <strong>liquide cérébrospinal</strong> ; Péridurale dans l'<strong>espace péridural</strong>.</li><li><strong>Aiguille</strong> : Rachi-anesthésie aiguille fine (<strong>25-27 G</strong>) ; Péridurale aiguille de Tuohy (<strong>16-18 G</strong>) avec cathéter.</li><li><strong>Confirmation du bon positionnement</strong> : Rachi-anesthésie par <strong>reflux de LCR</strong> ; Péridurale par <strong>perte de résistance</strong>.</li><li><strong>Délai d'action</strong> : Rachi-anesthésie en <strong>quelques minutes</strong> ; Péridurale <strong>plus lente</strong>.</li><li><strong>Zone anesthésiée</strong> : Rachi-anesthésie l'<strong>hémicorps inférieur</strong> ; Péridurale un <strong>blocage métamérique</strong>.</li><li><strong>Avantages</strong> : Rachi-anesthésie est <strong>simple</strong> et a un <strong>moindre risque traumatique</strong> ; Péridurale permet la <strong>titration des doses</strong> via cathéter, une <strong>meilleure analgésie post-opératoire prolongée</strong> et couvre <strong>tout type d'intervention</strong>.</li><li><strong>Inconvénients</strong> : Rachi-anesthésie a un <strong>risque hémodynamique non contrôlable</strong> ; Péridurale est une <strong>technique complexe</strong> avec un <strong>risque d'échec</strong>, d'<strong>hématome</strong>, de <strong>brèche dure-mérienne</strong> et d'<strong>infection du cathéter</strong>.</li></ul>"},{"i":"87e79143b777","n":136,"o":"136-7","u":"Prise en charge","t":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","q":"Quelles sont les complications spécifiques et les contre-indications de l'anesthésie locorégionale centrale (périmédullaire) ?","a":"<p>Les complications de l'ALR centrale sont liées à l'anesthésique et au geste :</p><ul><li><strong>Liées à l'anesthésique</strong> : Anaphylaxie, toxicité systémique (neurologique type <strong>crise convulsive</strong>, cardiaque type <strong>arrêt cardiaque</strong>), complications hémodynamiques (<strong>vasoplégie, hypotension majeure</strong>), respiratoires (si bloc trop élevé), et urinaires (<strong>difficultés mictionnelles, RAU</strong>).</li><li><strong>Liées au geste</strong> : <strong>Hématome péridural</strong> (favorisé par coagulopathie), <strong>infection</strong> (méningite, abcès), complications <strong>neurologiques</strong> (< 1/150 000 péridurales), et <strong>céphalées post-brèche</strong> (risque majoré avec aiguille de péridurale).</li></ul><p>Les contre-indications spécifiques à l'ALR centrale (en plus de celles communes à l'AL/ALR) sont :</p><ul><li><strong>Hypertension intra-crânienne</strong>.</li><li><strong>Cardiopathie évoluée</strong> (relative).</li></ul>"},{"i":"d89bb9c71bcf","n":136,"o":"136-7","u":"Prise en charge","t":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","q":"Quels sont les principes et les sites d'action des anesthésies locale et locorégionale ?","a":"<p>L'<strong>anesthésie locale</strong> agit directement en regard de la zone à traiter, souvent par infiltration ou voie topique, avec un effet rapide et de courte durée (ex: <strong>lidocaïne 60 min</strong>).</p><p>L'<strong>anesthésie locorégionale (ALR)</strong> interrompt transitoirement la conduction nerveuse sans abolir la conscience. Elle se décline en :</p><ul><li><strong>ALR centrale (périmédullaire)</strong> : réalise une ponction médiane lombaire en dessous de L2 (rachi-anesthésie ou péridurale).</li><li><strong>ALR périphérique</strong> : administration au niveau d'un plexus ou d'un tronc nerveux, guidé par échographie (ex: plexus brachial).</li></ul>"},{"i":"e35aa6615dca","n":136,"o":"136-7","u":"Prise en charge","t":"Connaître les principes d’une anesthésie locale et locorégionale, les indications, les principales complications","q":"Comment prévenir et prendre en charge l'intoxication aux anesthésiques locaux ?","a":"<p>La prévention de l'intoxication aux anesthésiques locaux repose sur :</p><ul><li>Le respect des <strong>doses maximales</strong>.</li><li>Un <strong>test d'aspiration</strong> avant injection.</li><li>Une <strong>injection fractionnée</strong> et à <strong>vitesse lente</strong>.</li><li>Le <strong>maintien du contact verbal</strong> avec le patient.</li></ul><p>La clinique associe des signes neurologiques (<strong>acouphènes, dysesthésies péribuccales, goût métallique, sensation ébrieuse</strong>, jusqu'aux <strong>convulsions généralisées</strong> et au <strong>coma</strong>) et cardiaques (<strong>troubles du rythme</strong> jusqu'à l'<strong>arrêt cardiaque</strong>).</p><p>La prise en charge immédiate inclut :</p><ul><li>L'<strong>arrêt de l'injection</strong> et l'appel à l'aide.</li><li>L'administration d'<strong>oxygène à 100 %</strong>.</li><li>Des <strong>benzodiazépines IV</strong> en cas de convulsion.</li><li>Un traitement symptomatique du coma et de l'arrêt cardiaque <strong>sans antiarythmique</strong>.</li><li>L'antidote spécifique est l'<strong>émulsion lipidique IV à 3 mL/kg</strong>.</li></ul>"}]};